--
-- Table structure for table `almacen_movimientos`
--

DROP TABLE IF EXISTS `almacen_movimientos`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `almacen_movimientos` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `producto_id` bigint unsigned NOT NULL,
  `detalle_compra_id` bigint unsigned DEFAULT NULL,
  `user_id` bigint unsigned NOT NULL,
  `almacen_id` bigint unsigned NOT NULL,
  `tipo` enum('entrada','salida') COLLATE utf8mb4_unicode_ci NOT NULL,
  `cantidad` int NOT NULL,
  `nota` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `tenant_id` bigint unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `almacen_movimientos_producto_id_foreign` (`producto_id`),
  KEY `almacen_movimientos_user_id_foreign` (`user_id`),
  KEY `almacen_movimientos_almacen_id_foreign` (`almacen_id`),
  KEY `almacen_movimientos_detalle_compra_id_foreign` (`detalle_compra_id`),
  KEY `almacen_movimientos_tenant_id_foreign` (`tenant_id`),
  CONSTRAINT `almacen_movimientos_almacen_id_foreign` FOREIGN KEY (`almacen_id`) REFERENCES `almacenes` (`id`) ON DELETE CASCADE,
  CONSTRAINT `almacen_movimientos_detalle_compra_id_foreign` FOREIGN KEY (`detalle_compra_id`) REFERENCES `compra_detalles` (`id`) ON DELETE CASCADE,
  CONSTRAINT `almacen_movimientos_producto_id_foreign` FOREIGN KEY (`producto_id`) REFERENCES `productos` (`id`) ON DELETE CASCADE,
  CONSTRAINT `almacen_movimientos_tenant_id_foreign` FOREIGN KEY (`tenant_id`) REFERENCES `business_instances` (`id`) ON DELETE SET NULL,
  CONSTRAINT `almacen_movimientos_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=85 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

