  `enabled` tinyint(1) NOT NULL DEFAULT '1',
  `sale_created` tinyint(1) NOT NULL DEFAULT '1',
  `sale_paid` tinyint(1) NOT NULL DEFAULT '1',
  `sale_cancelled` tinyint(1) NOT NULL DEFAULT '1',
  `order_confirmed` tinyint(1) NOT NULL DEFAULT '1',
