  `order_shipped` tinyint(1) NOT NULL DEFAULT '1',
  `payment_received` tinyint(1) NOT NULL DEFAULT '1',
  `credit_overdue` tinyint(1) NOT NULL DEFAULT '1',
  `credit_abono` tinyint(1) NOT NULL DEFAULT '1',
  `stock_critical` tinyint(1) NOT NULL DEFAULT '1',
  `stock_restocked` tinyint(1) NOT NULL DEFAULT '0',
  `product_created` tinyint(1) NOT NULL DEFAULT '0',
  `shift_opened` tinyint(1) NOT NULL DEFAULT '1',
  `shift_closed` tinyint(1) NOT NULL DEFAULT '1',
  `cash_shortage` tinyint(1) NOT NULL DEFAULT '1',
  `daily_report` tinyint(1) NOT NULL DEFAULT '0',
  `ncff_expiring` tinyint(1) NOT NULL DEFAULT '1',
  `ecf_certificate_expiring` tinyint(1) NOT NULL DEFAULT '1',
  `backup_completed` tinyint(1) NOT NULL DEFAULT '0',
  `backup_failed` tinyint(1) NOT NULL DEFAULT '1',
  `user_registered` tinyint(1) NOT NULL DEFAULT '1',
  `subscription_expiring` tinyint(1) NOT NULL DEFAULT '1',
  `subscription_suspended` tinyint(1) NOT NULL DEFAULT '1',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
