DROP TABLE IF EXISTS `ncf_sequences`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `ncf_sequences` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `nombre` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `prefijo` varchar(3) COLLATE utf8mb4_unicode_ci NOT NULL,
  `desde` bigint unsigned NOT NULL,
  `hasta` bigint unsigned NOT NULL,
  `actual` bigint unsigned NOT NULL,
  `fecha_vencimiento` date NOT NULL,
  `activo` tinyint(1) NOT NULL DEFAULT '1',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `tenant_id` bigint unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `ncf_sequences_tenant_id_foreign` (`tenant_id`),
  CONSTRAINT `ncf_sequences_tenant_id_foreign` FOREIGN KEY (`tenant_id`) REFERENCES `business_instances` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=40 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

