--
-- Table structure for table `ventas`
--

DROP TABLE IF EXISTS `ventas`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `ventas` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `tenant_id` bigint unsigned DEFAULT NULL,
  `sucursal_id` bigint unsigned DEFAULT NULL,
  `mesa_id` bigint unsigned DEFAULT NULL,
  `vehiculo_id` bigint unsigned DEFAULT NULL,
  `ncf` varchar(11) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `ncf_tipo` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `tipo_comprobante` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'ncf' COMMENT 'ncf (formato anterior), ecf (electrónico), ticket, sin_comprobante',
  `encf` varchar(13) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'e-CF generado',
  `ncf_vencimiento` date DEFAULT NULL,
  `user_id` bigint unsigned NOT NULL,
  `caja_id` bigint unsigned DEFAULT NULL,
  `sesion_caja_id` bigint unsigned DEFAULT NULL,
  `lista_precio_id` bigint unsigned DEFAULT NULL,
  `cliente_id` bigint unsigned DEFAULT NULL,
  `tipo_venta_id` bigint unsigned NOT NULL,
  `fecha` datetime NOT NULL DEFAULT '2026-08-26 14:42:47',
  `subtotal` decimal(10,2) NOT NULL,
  `impuestos` decimal(10,2) NOT NULL DEFAULT '0.00',
  `descuento` decimal(10,2) NOT NULL DEFAULT '0.00',
  `propina` decimal(12,2) NOT NULL DEFAULT '0.00',
  `cargo_servicio` decimal(12,2) NOT NULL DEFAULT '0.00',
  `descuento_tipo` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `descuento_motivo` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `notas` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `retencion_isr` decimal(12,2) NOT NULL DEFAULT '0.00',
  `retencion_itbis` decimal(12,2) NOT NULL DEFAULT '0.00',
  `total` decimal(10,2) NOT NULL,
  `ventas_count` int NOT NULL DEFAULT '0',
  `estado` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pendiente',
  `tipo_orden` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'mesa',
  `delivery_company_id` bigint unsigned DEFAULT NULL,
  `delivery_fee` decimal(10,2) NOT NULL DEFAULT '0.00',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `ventas_user_id_foreign` (`user_id`),
  KEY `ventas_cliente_id_foreign` (`cliente_id`),
  KEY `ventas_tipo_venta_id_foreign` (`tipo_venta_id`),
  KEY `ventas_caja_id_foreign` (`caja_id`),
  KEY `ventas_sesion_caja_id_foreign` (`sesion_caja_id`),
  KEY `ventas_lista_precio_id_foreign` (`lista_precio_id`),
  KEY `ventas_sucursal_id_foreign` (`sucursal_id`),
  KEY `ventas_mesa_id_foreign` (`mesa_id`),
  KEY `ventas_delivery_company_id_foreign` (`delivery_company_id`),
  KEY `ventas_vehiculo_id_foreign` (`vehiculo_id`),
  KEY `ventas_tenant_id_foreign` (`tenant_id`),
  CONSTRAINT `ventas_caja_id_foreign` FOREIGN KEY (`caja_id`) REFERENCES `cajas` (`id`) ON DELETE SET NULL,
  CONSTRAINT `ventas_cliente_id_foreign` FOREIGN KEY (`cliente_id`) REFERENCES `clientes` (`id`) ON DELETE SET NULL,
  CONSTRAINT `ventas_delivery_company_id_foreign` FOREIGN KEY (`delivery_company_id`) REFERENCES `delivery_companies` (`id`) ON DELETE SET NULL,
  CONSTRAINT `ventas_lista_precio_id_foreign` FOREIGN KEY (`lista_precio_id`) REFERENCES `lista_precios` (`id`) ON DELETE SET NULL,
  CONSTRAINT `ventas_mesa_id_foreign` FOREIGN KEY (`mesa_id`) REFERENCES `mesas` (`id`) ON DELETE SET NULL,
  CONSTRAINT `ventas_sesion_caja_id_foreign` FOREIGN KEY (`sesion_caja_id`) REFERENCES `sesion_cajas` (`id`) ON DELETE SET NULL,
  CONSTRAINT `ventas_sucursal_id_foreign` FOREIGN KEY (`sucursal_id`) REFERENCES `sucursales` (`id`) ON DELETE SET NULL,
  CONSTRAINT `ventas_tenant_id_foreign` FOREIGN KEY (`tenant_id`) REFERENCES `business_instances` (`id`) ON DELETE CASCADE,
  CONSTRAINT `ventas_tipo_venta_id_foreign` FOREIGN KEY (`tipo_venta_id`) REFERENCES `tipos_ventas` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `ventas_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE,
  CONSTRAINT `ventas_vehiculo_id_foreign` FOREIGN KEY (`vehiculo_id`) REFERENCES `vehiculos` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=70 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
